from typing import List

class Solution:
    def maxArea(self, height: List[int]) -> int:
        best = 0
        n = len(height)
        for i in range(n):
            max_right_height = 0
            for j in range(n - 1, i, -1):
                if height[j] <= max_right_height:
                    continue
                max_right_height = height[j]
                best = max(best, min(height[i], height[j]) * (j - i))
        return best

